import{_ as r,C as t,o as i,c as n,a6 as c,E as d,j as o,a}from"./chunks/framework.CKIbuWFA.js";const g=JSON.parse('{"title":"Prepare colaboração e acesso da equipe","description":"","frontmatter":{"title":"Prepare colaboração e acesso da equipe","docId":"user.cloud.collaboration","translationKey":"user.cloud.collaboration","locale":"pt","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4a97f64b6bdc818ebb8d16eec1e67d95a2d0eae0b75f7cfd5c1493bf27244684","translationRevision":"78cd6277049c86d1a964bfe0beedae96bf9c16ff951d055b6e5d4d23d91d31b8","order":30},"headers":[],"relativePath":"pt/user/cloud/collaboration.md","filePath":"pt/user/cloud/collaboration.md","lastUpdated":1794611623000}'),l={name:"pt/user/cloud/collaboration.md"};function p(u,e,m,b,v,f){const s=t("DemoFrame");return i(),n("div",null,[e[0]||(e[0]=c('<h1 id="prepare-collaboration-and-team-access" tabindex="-1">Prepare colaboração e acesso da equipe <a class="header-anchor" href="#prepare-collaboration-and-team-access" aria-label="Permalink to &quot;Prepare colaboração e acesso da equipe {#prepare-collaboration-and-team-access}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Conceda a outro operador um papel definido, mantendo o controle do proprietário. Você precisa de um host de desktop com as capacidades necessárias e de uma escolha consciente entre colaboração local/nativa e Teams baseado em conta. Teams também precisa de <a href="./account.html">login no Cloud</a> e suporte correspondente do serviço implantado. Comece com acesso somente de leitura e uma configuração fora de produção.</p><h2 id="configure-owner-access" tabindex="-1">Configure o acesso do proprietário <a class="header-anchor" href="#configure-owner-access" aria-label="Permalink to &quot;Configure o acesso do proprietário {#configure-owner-access}&quot;">​</a></h2><ol><li>Abra <strong>Settings → Collaboration</strong>. Inspecione o status da conexão e ative/configure o receptor ou gateway desejado pelos controles.</li><li>Revise as origens permitidas e a matriz de acesso antes de criar um convite. Escolha apenas as áreas, operações e recursos de que o operador precisa.</li><li>Crie um convite e entregue seu link/token privado por um canal confiável. Um convite não é o mesmo que uma sessão ativa aprovada.</li><li>Inspecione as solicitações pendentes e a concessão solicitada. Aprove apenas o operador esperado, depois confirme sua identidade visível e conexão.</li><li>Use o inspetor de acesso para revisar alterações posteriores nas concessões. Revogue convites, identidades ou sessões quando o acesso não for mais necessário.</li></ol><p>Edição delegada de definições, adoção de uma definição como proprietário e aprovação de execução delegada são decisões distintas. Leia a origem salva, as ações referenciadas e as permissões na revisão específica. Uma prévia de definição sozinha não autoriza um efeito.</p><h2 id="prepare-an-account-based-team" tabindex="-1">Prepare uma equipe baseada em conta <a class="header-anchor" href="#prepare-an-account-based-team" aria-label="Permalink to &quot;Prepare uma equipe baseada em conta {#prepare-an-account-based-team}&quot;">​</a></h2><p>Quando <strong>Settings → Teams</strong> estiver disponível, crie uma equipe com nome e selecione-a. Registre <strong>this PC</strong> como host com um rótulo de dispositivo reconhecível, depois use <strong>Start serving</strong> e inspecione o estado do vínculo. A criação e o registro do host local estão conectados no frontend; são separados do convite a um colega. Um dispositivo controlador tem seu próprio papel de registro.</p><p>Escolha um destinatário, papel e duração do convite, depois revise solicitações recebidas, membros e dispositivos. O fluxo de busca por apelido exige um endpoint de backend implantado separadamente e pode estar indisponível no serviço atual. Não presuma que uma busca que falhou significa que a pessoa não tem conta nem substitua a seleção por um ID arbitrário.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Existem controles de acesso do proprietário e criação/registro de equipes no frontend. O fluxo completo de colaboração remota é experimental: operação real de LIVE entre dois PCs, busca de apelidos em produção, comportamento de NAT/relay e todos os caminhos de recuperação por plataforma/efeito não estão comprovados aqui. Um vínculo pronto sozinho não comprova a aplicação de permissões de ponta a ponta para sua ação pretendida.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Para concessões ou revisões do host desatualizadas, recarregue e revise novamente. Para comandos não confirmados, inspecione o resultado registrado antes de tentar novamente. Pare de servir ou revogue o acesso ao encerrar uma sessão. Mantenha tokens de convite e credenciais fora de <a href="./../preferences/troubleshooting.html">relatórios de diagnóstico</a> públicos.</p>',13)),d(s,{scenario:"collaboration",locale:"pt",title:"Demonstração: colaboração"}),e[1]||(e[1]=o("h2",{id:"operational-details",tabindex:"-1"},[a("Detalhes de operação "),o("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Detalhes de operação {#operational-details}"'},"​")],-1)),e[2]||(e[2]=o("p",null,[a("Após entrar/aprovar acesso Teams, o host confirma a revisão atual da permissão nativa. "),o("code",null,"pendingHost"),a(" indica espera; transporte ativo ou participação não concedem acesso sozinhos. Atualize após alterar permissões e confira host/dispositivo. Observer é de leitura; moderator acrescenta controles selecionados, automationEditor edição selecionada e custom exige política explícita revisada. Nenhum concede scripts/efeitos irrestritos. Veja "),o("a",{href:"./../../developer/collaboration.html#operational-details"},"papéis e confirmação"),a(" se os controles não explicarem uma recusa.")],-1))])}const q=r(l,[["render",p]]);export{g as __pageData,q as default};
